const toast=document.getElementById('toast');let toastTimer;function showToast(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2400)}const title=document.getElementById('title'),subtitle=document.getElementById('subtitle');document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>{const view=btn.dataset.view;if(btn.matches('nav button')){document.querySelectorAll('nav button').forEach(b=>b.classList.remove('active'));btn.classList.add('active')}document.getElementById('crumb').textContent=view;if(view==='Dashboard'){title.innerHTML='Good morning, John <span>✦</span>';subtitle.textContent='Here’s what’s happening across your revenue team today.'}else{title.textContent=view;subtitle.textContent='Explore '+view.toLowerCase()+' in your Lead360 AI workspace.';showToast(view+' preview selected · Demo workspace')}document.getElementById('modal').classList.remove('show')}));document.getElementById('create').onclick=()=>document.getElementById('modal').classList.add('show');document.getElementById('closeModal').onclick=()=>document.getElementById('modal').classList.remove('show');document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('show')};document.getElementById('dismiss').onclick=()=>document.querySelector('.notice').remove();document.getElementById('range').onclick=()=>showToast('Showing illustrative performance for the last 30 days');document.getElementById('privacy').onclick=e=>{e.preventDefault();showToast('Data controls are part of the product roadmap')};document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>showToast('Prospect filters · Demo workspace'));document.querySelectorAll('.rowmore').forEach(b=>b.onclick=()=>showToast('Contact actions are simulated in this demo'));document.querySelectorAll('.table-foot button').forEach(b=>b.onclick=()=>showToast('You’re viewing the first sample page'));document.getElementById('prospectSearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#prospects tr').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(q)?'':'none')});let ran=false;document.getElementById('runPrompt').onclick=async e=>{const b=e.currentTarget;b.disabled=true;b.textContent='✦  Finding prospects…';await new Promise(r=>setTimeout(r,650));document.getElementById('promptText').textContent=ran?'Find B2B software companies hiring sales teams in the Midwest.':'Find manufacturing companies in Minnesota with 50–500 employees and purchasing leaders.';document.getElementById('resultCompanies').textContent=ran?'312':'428';document.getElementById('resultContacts').textContent=ran?'946':'1,284';document.getElementById('resultVerified').textContent=ran?'704':'967';document.getElementById('resultPriority').textContent=ran?'124':'186';ran=!ran;b.disabled=false;b.innerHTML='✦ &nbsp; Find prospects';showToast('Sample prospect search complete')};
